-- CP stores authoring and public issuance facts, never a CA key or raw token.
CREATE TABLE managed_nodes(id TEXT PRIMARY KEY,site_id TEXT NOT NULL,node_json TEXT NOT NULL,authority_epoch BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE node_enrollments(id TEXT PRIMARY KEY,node_id TEXT NOT NULL REFERENCES managed_nodes(id),role TEXT NOT NULL CHECK(role='agent'),token_hash TEXT UNIQUE NOT NULL,authority_epoch BIGINT NOT NULL,state TEXT NOT NULL CHECK(state IN ('issued','csr_pending','approved','issued_certificate','revoked')),expires_at TIMESTAMPTZ NOT NULL,request_digest TEXT NOT NULL DEFAULT '',public_key_digest TEXT NOT NULL DEFAULT '',csr_pem TEXT NOT NULL DEFAULT '',reservation_json TEXT NOT NULL DEFAULT '',approved_by TEXT NOT NULL DEFAULT '',approval_security_version BIGINT NOT NULL DEFAULT 0,approval_password_version BIGINT NOT NULL DEFAULT 0,approval_digest TEXT NOT NULL DEFAULT '',certificate_json TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX node_enrollments_active_idx ON node_enrollments(node_id,role,state);
CREATE TABLE node_identity_requests(actor_id TEXT NOT NULL,operation TEXT NOT NULL,request_key TEXT NOT NULL,request_digest TEXT NOT NULL,result_json TEXT NOT NULL,authority_epoch BIGINT NOT NULL,PRIMARY KEY(actor_id,operation,request_key));
CREATE TABLE node_enrollment_limits(bucket TEXT PRIMARY KEY,window_start TIMESTAMPTZ NOT NULL,attempts INTEGER NOT NULL CHECK(attempts>0));
INSERT INTO permissions(id,description) VALUES('nodes.read','Read authorized node inventory'),('nodes.enroll','Enroll agent identities'),('nodes.revoke','Revoke agent enrollment');
